def min_performance_duration(a, b, c, d):
    # Sort the positions to easily identify the maximum gap
    positions = sorted([a, b, c])

    # Calculate the gaps between consecutive positions
    gap1 = positions[1] - positions[0]
    gap2 = positions[2] - positions[1]

    # Determine the minimum number of steps required to close the gaps
    if gap1 >= d and gap2 >= d:
        return 0
    elif gap1 + gap2 < d:
        return d - (gap1 + gap2)
    else:
        return max(d - gap1, d - gap2)

